fn solve(w: i8, a: i8, b: i8) -> i8 {
    // Compute the absolute distance between the left endpoints
    let distance = (a - b).abs();
    // If they already touch or overlap, no shift needed (return 0).
    // Otherwise, subtract the width to get the required shift.
    if distance <= w {
        0
    } else {
        distance - w
    }
}

